38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateEmailException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
45	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
47	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
